import React, { useState, useEffect } from 'react';

const PaymentModal = ({ show, cartTotal, onConfirm, onCancel, showToast, paymentMethod }) => {
  const [cashReceived, setCashReceived] = useState('');
  const [changeDue, setChangeDue] = useState(0);

  const formatPrice = (price) =>
    new Intl.NumberFormat('es-CL', {
      style: 'currency',
      currency: 'CLP',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(price);

  useEffect(() => {
    if (show) {
      setCashReceived('');
      setChangeDue(0);
    }
  }, [show, paymentMethod]);

  useEffect(() => {
    const received = parseInt(cashReceived, 10) || 0;
    setChangeDue(received >= cartTotal ? received - cartTotal : 0);
  }, [cashReceived, cartTotal]);

  const handleInput = (e) => {
    const value = e.target.value.replace(/[^0-9]/g, '');
    setCashReceived(value);
  };

  const handleAutoComplete = () => {
    setCashReceived(cartTotal.toString());
  };

  const handleConfirm = () => {
    if (paymentMethod === 'Efectivo') {
      const received = parseInt(cashReceived, 10) || 0;
      if (received < cartTotal) {
        if (showToast) showToast('Monto Insuficiente', 'El monto recibido es menor que el total de la venta.', 'error');
        return;
      }
      onConfirm(received, changeDue);
    } else {
      onConfirm(null, null);
    }
  };

  if (!show) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-lg p-6 max-w-sm w-full">
        <h5 className="font-bold mb-2">Confirmar Venta</h5>
        <p className="mb-4">Total a pagar: <strong>{formatPrice(cartTotal)}</strong></p>
        {paymentMethod === 'Efectivo' ? (
          <>
            <div className="mb-3">
              <label htmlFor="cashReceivedInput" className="block font-medium mb-1">Monto recibido:</label>
              <input
                id="cashReceivedInput"
                type="number"
                className="border rounded px-3 py-2 w-full"
                value={cashReceived}
                onChange={handleInput}
                placeholder="Ingrese el monto..."
                min="0"
                autoFocus
              />
            </div>
            <div className="flex justify-between mb-3 font-bold">
              <span>Vuelto:</span>
              <span>{formatPrice(changeDue)}</span>
            </div>
            <div className="flex justify-end gap-2">
              <button className="bg-gray-300 hover:bg-gray-400 text-gray-800 rounded px-4 py-2" onClick={onCancel}>Cancelar</button>
              <button
                className="bg-green-600 hover:bg-green-700 text-white rounded px-4 py-2"
                onClick={handleConfirm}
                disabled={parseInt(cashReceived, 10) < cartTotal || !cashReceived}
              >
                Pagar
              </button>
            </div>
          </>
        ) : paymentMethod === 'Tarjeta' ? (
          <>
            <div className="mb-6 text-center">
              <span className="block text-lg font-semibold mb-2">Pago con Tarjeta</span>
              <span className="block text-2xl font-bold text-green-700">{formatPrice(cartTotal)}</span>
            </div>
            <div className="flex justify-end gap-2">
              <button className="bg-gray-300 hover:bg-gray-400 text-gray-800 rounded px-4 py-2" onClick={onCancel}>Cancelar</button>
              <button
                className="bg-blue-600 hover:bg-blue-700 text-white rounded px-4 py-2"
                onClick={() => onConfirm(null, null)}
              >
                Completar venta
              </button>
            </div>
          </>
        ) : null}
      </div>
    </div>
  );
};

export default PaymentModal;
